import { Account, Client, ID, Query, TablesDB } from "appwrite";

// Loopback is always the isolated Docker project. Published hosts use Android's debug database.
const local = ["localhost", "127.0.0.1"].includes(location.hostname);
const endpoint = local ? "http://127.0.0.1/v1" : "https://cloud.appwrite.io/v1";
const project = local ? "6a9ae2610009473c400b" : "68737bb2001332a78029";
const databaseId = local ? "heroquest_local_test" : "68add59a00211eef8c16";
const users = "687633f3002058257f2b";
const heroes = "6889b6c20038666a07ca";
const client = new Client().setEndpoint(endpoint).setProject(project);
const account = new Account(client);
const tables = new TablesDB(client);

export async function currentUser() {
  try {
    return (await account.get()).$id;
  } catch (error) {
    if (error.code === 401) return "";
    throw error;
  }
}

async function loginOnce(username, password) {
  const { rows } = await tables.listRows({ databaseId, tableId: users,
    queries: [Query.equal("username", username), Query.limit(1)] });
  const email = rows.length ? rows[0].email : `${username}@${username}.de`;
  await account.createEmailPasswordSession({ email, password });
  const user = await account.get();
  if (!rows.length && user.name !== username) {
    await signOut();
    throw new Error("Benutzername stimmt nicht überein.");
  }
  if (!rows.length) {
    try {
      await tables.createRow({ databaseId, tableId: users, rowId: user.$id, data: { username, email } });
    } catch { /* A later verified login retries an interrupted mapping repair. */ }
  }
  return user.$id;
}

export async function readHero(rowId) {
  try {
    return await tables.getRow({ databaseId, tableId: heroes, rowId });
  } catch (error) {
    if (error.type === "row_not_found" || error.type === "document_not_found") return null;
    throw error;
  }
}

export function watchHero(rowId, refresh) {
  return client.subscribe(`tablesdb.${databaseId}.tables.${heroes}.rows.${rowId}`, refresh);
}

export function signOut() {
  return account.deleteSession({ sessionId: "current" });
}

export async function maintenance() {
  try {
    const config = await tables.getRow({ databaseId, tableId: "687fc8f5001c479e10c7", rowId: "active" });
    return config.loginDisabled === true;
  } catch { return false; } // Android AdminRepository falls back to login enabled.
}

export async function authenticate(username, password, register) {
  if (await maintenance() && (register || username.toLowerCase() !== "admin")) return "maintenance";
  if (register) {
    const email = username + "@" + username + ".de";
    try {
      await account.create({ userId: ID.unique(), name: username, email, password });
    } catch (error) {
      if (error.code === 409) return "taken";
      throw error;
    }
    await tables.createRow({ databaseId, tableId: users, rowId: ID.unique(), data: { username, email } });
  }
  for (let attempt = 1; ; attempt++) {
    try { return "ok:" + await loginOnce(username, password); }
    catch (error) {
      if (error.code !== 429 || attempt === 3) throw error;
      await new Promise(resolve => setTimeout(resolve, 2000 * attempt));
    }
  }
}

export async function createHero(name, heroClass, title, gold, adventure) {
  const user = await account.get();
  const data = { userId: user.$id, userName: user.name, name, class: heroClass, title, gold, potions: "{}" };
  if (adventure) data.adventure = adventure;
  // A create-only write also protects concurrent creation and existing gold.
  try { await tables.createRow({ databaseId, tableId: heroes, rowId: user.$id, data }); }
  catch (error) { if (error.type !== "row_already_exists" && error.type !== "document_already_exists") throw error; }
}

export async function equippedItems(heroeId) {
  const tableId = "69999e83002ba95aa0b7";
  const { rows } = await tables.listRows({ databaseId, tableId,
    queries: [Query.equal("heroeId", heroeId), Query.limit(100)] });
  const items = await Promise.all(rows.map(async slot => {
    try {
      const item = await tables.getRow({ databaseId, tableId: "687527c10003d8fe2678", rowId: slot.inventoryItemId });
      return item.heroeId === heroeId ? { ...item, slot: slot.slot } : null;
    } catch (error) {
      if (["row_not_found", "document_not_found"].includes(error.type)) return null;
      throw error;
    }
  }));
  return JSON.stringify(items.filter(Boolean));
}
